function commitIndex(matchIndex) {
  const sorted = [...matchIndex].sort((a, b) => b - a);
  const majority = Math.floor(matchIndex.length / 2) + 1;
  return sorted[majority - 1];
}
commitIndex([10, 9, 7, 4, 2]); // 7  (majority = 3: nodes with 10, 9, 7)
commitIndex([5, 5, 5, 1]);     // 5  (majority = 3 of 4)
```
O(n log n) for the sort; n is tiny (3–7) so that is fine.
